     pub open spec fn wf_readstate(&self, rs: ReadonlyState<DT>) -> bool {
         match rs {
             ReadonlyState::Init{op} => {
                 true
             }
             ReadonlyState::VersionUpperBound{op, version_upper_bound} => {
                 version_upper_bound <= self.version_upper_bound
